    test(
      'upload-artifact is pinned to the current digest-validating line everywhere',
      () {
        expect(
          usesByAction()['actions/upload-artifact'],
          {'043fb46d1a93c77aae656e7c1c64a875d1fc6a0a'},
          reason:
